package com.rustypayments.legacy;

import java.text.ParseException;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.TimeZone;

/**
 * DATE HELPERS
 * CREATED 03.05.2002
 * CHG 21.11.2006 - formatters made static, "was allocating thousands of them in the nightly run"
 * CHG 14.01.2011 - YYYY for the year, as the new standard asks
 */
public class DateUtil {

    private static final SimpleDateFormat DAY_IN = new SimpleDateFormat("yyyy-MM-dd");
    private static final SimpleDateFormat DAY_OUT = new SimpleDateFormat("YYYY-MM-dd");
    private static final SimpleDateFormat INSTANT_IN =
            new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ssXXX");

    public static Date parseDay(String text) {
        if (text == null) {
            throw new IllegalArgumentException("INVALID DATE");
        }
        try {
            DAY_IN.setTimeZone(TimeZone.getDefault());
            return DAY_IN.parse(text.trim());
        } catch (ParseException e) {
            throw new IllegalArgumentException("INVALID DATE: " + text);
        }
    }

    public static Date parseInstant(String text) {
        if (text == null) {
            throw new IllegalArgumentException("INVALID TIMESTAMP");
        }
        try {
            INSTANT_IN.setTimeZone(TimeZone.getDefault());
            return INSTANT_IN.parse(text.trim());
        } catch (ParseException e) {
            throw new IllegalArgumentException("INVALID TIMESTAMP: " + text);
        }
    }

    public static String formatDay(Date date) {
        DAY_OUT.setTimeZone(TimeZone.getDefault());
        return DAY_OUT.format(date);
    }
}

package com.rustypayments.legacy;

import java.util.Calendar;

/**
 * BANK HOLIDAYS (fixed dates only)
 * CHG 02.01.2005 - added 3 May after branch 0017 stayed open
 */
public class HolidayTable {

    /** Month is 0-based, the way Calendar wants it. */
    private static final int[][] HOLIDAYS = {
        {0, 1},    // New Year
        {4, 1},    // Labour Day
        {4, 3},    // Constitution Day
        {7, 15},   // Assumption
        {10, 1},   // All Saints
        {10, 11},  // Independence Day
        {11, 25},  // Christmas
        {11, 26}   // Boxing Day
    };

    public static boolean isHoliday(Calendar day) {
        int month = day.get(Calendar.MONTH);
        int date = day.get(Calendar.DAY_OF_MONTH);
        for (int i = 0; i < HOLIDAYS.length; i++) {
            if (HOLIDAYS[i][0] == month && HOLIDAYS[i][1] == date) {
                return true;
            }
        }
        return false;
    }
}

package com.rustypayments.legacy;

import com.rustypayments.PaymentCalendar;

import java.util.Calendar;
import java.util.Date;

/**
 * PAYMENT CALENDAR
 * CREATED 03.05.2002
 * CHG 30.08.2008 - cut-off moved from 15:00 to 16:00
 * CHG 09.09.2009 - migrated from the green screens, logic unchanged
 */
public class LegacyPaymentCalendar implements PaymentCalendar {

    private static final long DAY_MILLIS = 24L * 60 * 60 * 1000;

    public boolean isBusinessDay(String date) {
        Calendar c = Calendar.getInstance();
        c.setTime(DateUtil.parseDay(date));
        return isBusinessDay(c);
    }

    public String processingDate(String submittedAt) {
        return DateUtil.formatDay(processing(submittedAt).getTime());
    }

    public String settlementDate(String submittedAt) {
        Calendar processing = processing(submittedAt);
        return DateUtil.formatDay(nextBusinessDay(processing).getTime());
    }

    public int daysLate(String dueDate, String paidAt) {
        Date due = DateUtil.parseDay(dueDate);
        Date paid = DateUtil.parseInstant(paidAt);
        long late = (paid.getTime() - due.getTime()) / DAY_MILLIS;
        return late < 0 ? 0 : (int) late;
    }

    public String addMonths(String date, int months) {
        Calendar c = Calendar.getInstance();
        c.setTime(DateUtil.parseDay(date));
        c.add(Calendar.MONTH, months);
        return DateUtil.formatDay(c.getTime());
    }

    private Calendar processing(String submittedAt) {
        Calendar c = Calendar.getInstance();
        c.setTime(DateUtil.parseInstant(submittedAt));
        int hour = c.get(Calendar.HOUR_OF_DAY);
        int minute = c.get(Calendar.MINUTE);
        boolean inTime = hour < 16 || (hour == 16 && minute == 0);
        if (isBusinessDay(c) && inTime) {
            return c;
        }
        return nextBusinessDay(c);
    }

    private Calendar nextBusinessDay(Calendar from) {
        Calendar c = (Calendar) from.clone();
        do {
            c.add(Calendar.DATE, 1);
        } while (!isBusinessDay(c));
        return c;
    }

    private boolean isBusinessDay(Calendar c) {
        int dayOfWeek = c.get(Calendar.DAY_OF_WEEK);
        if (dayOfWeek == Calendar.SATURDAY || dayOfWeek == Calendar.SUNDAY) {
            return false;
        }
        return !HolidayTable.isHoliday(c);
    }
}
